//! LANG84 R0 differential tests: the grammar-driven lexer over
//! `ruby3.3.6.tokens` against two references, on the corpus in
//! `tests/fixtures/r0/` (R0-only programs; every one passes `ruby -c`).
//!
//! 1. **Ripper.lex of the host Ruby 3.3.6** — the oracle. Its output is
//!    committed beside each program (`<name>.ripper`, regenerated by
//!    `tests/fixtures/ripper_oracle.rb`), so the comparison runs without a
//!    Ruby installation. Every token must agree on kind, spelling, line and
//!    column, and every newline Ripper reports must be a NEWLINE here.
//!    When the `ruby` on PATH is 3.3.6, the oracle files are also checked
//!    against a fresh `Ripper.lex` run.
//! 2. **The hand-written `ruby-lexer`** (era "3.3") that LANG84 replaces.
//!    Spellings are compared token by token. Where they differ, the program
//!    must be listed in `KNOWN_RUBY_LEXER_DIVERGENCES` with the reason; the
//!    Ripper comparison above has already shown that the grammar lexer is
//!    the side that agrees with Ruby.

use std::path::{Path, PathBuf};

use coding_adventures_ruby_lexer::tokenize_ruby_for_version;
use coding_adventures_ruby_parser::{tokenize_ruby_at, FrontendBudgets};
use lexer::token::{Token, TokenType};

const ORACLE_RELEASE: &str = "3.3.6";

fn corpus() -> Vec<(String, String, PathBuf)> {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/r0");
    let mut files: Vec<_> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .filter(|path| path.extension().is_some_and(|ext| ext == "rb"))
        .collect();
    files.sort();
    files
        .into_iter()
        .map(|path| {
            let name = path.file_stem().unwrap().to_string_lossy().to_string();
            let source = std::fs::read_to_string(&path).unwrap();
            (name, source, path.with_extension("ripper"))
        })
        .collect()
}

fn kind(token: &Token) -> &str {
    token.effective_type_name()
}

/// The Ripper event a grammar-lexer token corresponds to.
fn ripper_event(token: &Token) -> &'static str {
    match kind(token) {
        "NUMBER" | "HEX_INTEGER" | "BINARY_INTEGER" | "OCTAL_INTEGER"
        | "DECIMAL_PREFIXED_INTEGER" => "on_int",
        "FLOAT" => "on_float",
        "NAME" | "FID" => "on_ident",
        "CONSTANT" => "on_const",
        "KEYWORD" => "on_kw",
        "IVAR" => "on_ivar",
        "CVAR" => "on_cvar",
        "GVAR" => "on_gvar",
        "NTH_REF" | "BACK_REF" => "on_backref",
        "CHAR" => "on_CHAR",
        "SYMBEG" => "on_symbeg",
        "LPAREN" => "on_lparen",
        "RPAREN" => "on_rparen",
        "LBRACKET" => "on_lbracket",
        "RBRACKET" => "on_rbracket",
        "LBRACE" => "on_lbrace",
        "RBRACE" => "on_rbrace",
        "COMMA" => "on_comma",
        "SEMICOLON" => "on_semicolon",
        "DOT" => "on_period",
        "LAMBDA" => "on_tlambda",
        _ => "on_op",
    }
}

type Positioned = (usize, usize, String, String); // line, 0-based column, event, value

fn unescape(value: &str) -> String {
    let mut out = String::new();
    let mut chars = value.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('n') => out.push('\n'),
                Some('t') => out.push('\t'),
                Some('\\') => out.push('\\'),
                other => panic!("bad escape {other:?}"),
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// (tokens, newline positions) from an oracle file.
fn read_oracle(text: &str) -> (Vec<Positioned>, Vec<(usize, usize)>) {
    let mut tokens = Vec::new();
    let mut newlines = Vec::new();
    for row in text.lines().filter(|row| !row.starts_with('#')) {
        let cells: Vec<&str> = row.splitn(4, '\t').collect();
        let [line, column, event, value] = cells.as_slice() else {
            panic!("bad oracle row {row:?}");
        };
        let (line, column) = (line.parse().unwrap(), column.parse::<usize>().unwrap());
        let value = unescape(value);
        match *event {
            "on_nl" | "on_ignored_nl" => newlines.push((line, column)),
            "on_comment" => {
                if value.ends_with('\n') {
                    newlines.push((line, column + value.len() - 1));
                }
            }
            // `->` is followed by tLAMBEG, which is an ordinary `{` token here.
            "on_tlambeg" => tokens.push((line, column, "on_lbrace".into(), value)),
            _ => tokens.push((line, column, event.to_string(), value)),
        }
    }
    (tokens, newlines)
}

fn grammar_tokens(release: &str, source: &str) -> Vec<Token> {
    let (_, tokens) = tokenize_ruby_at(source, Some(release), &FrontendBudgets::default())
        .unwrap_or_else(|error| panic!("{error}"));
    tokens
}

fn split_newlines(tokens: &[Token]) -> (Vec<Positioned>, Vec<(usize, usize)>) {
    let mut rest = Vec::new();
    let mut newlines = Vec::new();
    for token in tokens {
        match token.type_ {
            TokenType::Eof => {}
            TokenType::Newline => newlines.push((token.line, token.column - 1)),
            _ => rest.push((
                token.line,
                token.column - 1,
                ripper_event(token).to_string(),
                token.value.clone(),
            )),
        }
    }
    (rest, newlines)
}

#[test]
fn grammar_lexer_matches_committed_ripper_oracle() {
    let mut compared = 0;
    for (name, source, oracle_path) in corpus() {
        let oracle = std::fs::read_to_string(&oracle_path)
            .unwrap_or_else(|_| panic!("{name}: missing oracle; run ripper_oracle.rb"));
        assert!(
            oracle.starts_with("# oracle: Ripper.lex, ruby 3.3.6 "),
            "{name}: the oracle must come from ruby 3.3.6, the release it is checked against"
        );
        let (expected, expected_newlines) = read_oracle(&oracle);
        let (actual, actual_newlines) = split_newlines(&grammar_tokens(ORACLE_RELEASE, &source));
        assert_eq!(actual, expected, "{name}: tokens differ from Ripper.lex");
        assert_eq!(actual_newlines, expected_newlines, "{name}: newlines differ from Ripper.lex");
        compared += expected.len();
    }
    // Pin the corpus size so a deleted fixture cannot silently shrink the check.
    assert_eq!(corpus().len(), 22);
    assert!(compared > 500, "only {compared} tokens compared");
}

#[test]
fn committed_oracle_matches_host_ripper_when_it_is_3_3_6() {
    let script = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/ripper_oracle.rb");
    let version = std::process::Command::new("ruby")
        .args(["-e", "print RUBY_VERSION"])
        .output();
    let Ok(version) = version else {
        eprintln!("skipped: no `ruby` on PATH; the committed oracle is still checked");
        return;
    };
    if version.stdout != b"3.3.6" {
        eprintln!("skipped: host ruby is not 3.3.6");
        return;
    }
    // Re-run the generator into a scratch copy of the corpus and compare.
    let scratch = std::env::temp_dir().join(format!("ruby-r0-oracle-{}", std::process::id()));
    let corpus_dir = scratch.join("r0");
    std::fs::create_dir_all(&corpus_dir).unwrap();
    std::fs::copy(&script, scratch.join("ripper_oracle.rb")).unwrap();
    for (name, source, _) in corpus() {
        std::fs::write(corpus_dir.join(format!("{name}.rb")), source).unwrap();
    }
    let status = std::process::Command::new("ruby")
        .arg(scratch.join("ripper_oracle.rb"))
        .status()
        .unwrap();
    assert!(status.success());
    for (name, _, oracle_path) in corpus() {
        let fresh = std::fs::read_to_string(corpus_dir.join(format!("{name}.ripper"))).unwrap();
        let committed = std::fs::read_to_string(oracle_path).unwrap();
        assert_eq!(fresh, committed, "{name}: committed oracle is stale");
    }
    std::fs::remove_dir_all(scratch).unwrap();
}

/// Programs where the hand-written lexer's spellings differ from the grammar
/// lexer's, with the reason. The grammar lexer's side of each is the one the
/// Ripper oracle confirms.
const KNOWN_RUBY_LEXER_DIVERGENCES: &[(&str, &str)] = &[
    (
        "05_variables",
        "ruby-lexer splits the punctuation globals `$~`, `$:`, `$-w`, `$&`, ... into `$` plus an operator",
    ),
    (
        "07_chars",
        "ruby-lexer splits the character literal `?a` into `?` and `a`",
    ),
    (
        "09_operators",
        "ruby-lexer reads `a / b` as the start of an unterminated regexp and silently drops the rest of the input",
    ),
    (
        "19_unary",
        "ruby-lexer splits `+4` into `+` and `4`; parse.y folds the sign into the literal in EXPR_BEG",
    ),
    (
        "22_plus_sign",
        "ruby-lexer splits `+1`, `+0x1F`, `+1.5`, `+0b1` and `+2` after `[`, `,` and `(`",
    ),
];

fn spellings(tokens: &[Token]) -> Vec<String> {
    tokens
        .iter()
        .filter(|t| !matches!(t.type_, TokenType::Newline | TokenType::Eof))
        .map(|t| t.value.clone())
        .collect()
}

#[test]
fn grammar_lexer_against_hand_written_ruby_lexer() {
    let mut agree = Vec::new();
    let mut differ = Vec::new();
    for (name, source, _) in corpus() {
        let grammar = spellings(&grammar_tokens(ORACLE_RELEASE, &source));
        let legacy = tokenize_ruby_for_version(&source, "3.3")
            .map(|tokens| spellings(&tokens))
            .unwrap_or_else(|error| vec![format!("<ruby-lexer error: {error}>")]);
        if grammar == legacy {
            agree.push(name);
        } else {
            let first = grammar
                .iter()
                .zip(&legacy)
                .position(|(a, b)| a != b)
                .unwrap_or(grammar.len().min(legacy.len()));
            differ.push((
                name,
                grammar.get(first).cloned(),
                legacy.get(first).cloned(),
            ));
        }
    }
    eprintln!("ruby-lexer agrees on {} programs: {:?}", agree.len(), agree);
    for (name, grammar, legacy) in &differ {
        eprintln!("ruby-lexer differs on {name}: grammar {grammar:?} vs ruby-lexer {legacy:?}");
    }
    let listed: Vec<&str> = KNOWN_RUBY_LEXER_DIVERGENCES.iter().map(|(n, _)| *n).collect();
    let actual: Vec<&str> = differ.iter().map(|(n, _, _)| n.as_str()).collect();
    assert_eq!(actual, listed, "divergence list is out of date");
}
